/**
 * build-redirects.js — writes public/_redirects for Cloudflare Pages from
 * content/shop-canonical.json (duplicate product pages → canonical, 301).
 * Runs before `next build` (see package.json "prebuild").
 */
const fs = require('fs');
const path = require('path');
const map = JSON.parse(fs.readFileSync(path.join(process.cwd(), 'content', 'shop-canonical.json'), 'utf-8'));
const lines = [
  '# generated by scripts/build-redirects.js — do not edit',
  // www → apex (Netlify used to do this)
  'https://www.valuefindsdaily.com/* https://valuefindsdaily.com/:splat 301',
];
for (const [from, to] of Object.entries(map)) if (from !== to) lines.push(`/shop/${from} /shop/${to} 301`);
lines.push('/shop/freebie /freebie 301');
fs.writeFileSync(path.join(process.cwd(), 'public', '_redirects'), lines.join('\n') + '\n');
console.log(`_redirects: ${lines.length - 1} rules`);
